Literal.Value:
'{
  "data": {
    "name": "dataset"
  },
  "width": "container",
  "height": "container",
  "padding": {
    "top": 16
  },
  "transform": [
    {
      "filter": "isValid(datum[''Tarifa sem tributos 12m'']) && isValid(datum[''ICMS efetivo 12m''])"
    },
    {
      "joinaggregate": [
        {
          "op": "median",
          "field": "Tarifa sem tributos 12m",
          "as": "mx"
        },
        {
          "op": "median",
          "field": "ICMS efetivo 12m",
          "as": "my"
        }
      ]
    },
    {
      "calculate": "indexof(datum[''Métrica escolhida''], ''ICMS'') >= 0 ? format(datum[''Valor do mapa''], ''.1%'') : format(datum[''Valor do mapa''], ''$,.2f'')",
      "as": "rotulo"
    }
  ],
  "layer": [
    {
      "transform": [
        {
          "window": [
            {
              "op": "row_number",
              "as": "k"
            }
          ]
        },
        {
          "filter": "datum.k == 1"
        }
      ],
      "mark": {
        "type": "rule",
        "color": "#A19F9D",
        "strokeDash": [
          4,
          3
        ]
      },
      "encoding": {
        "x": {
          "field": "mx",
          "type": "quantitative",
          "scale": {
            "zero": false
          },
          "title": "Tarifa sem tributos (R$/kWh)",
          "axis": {
            "format": "$,.2f",
            "tickCount": 4
          }
        }
      }
    },
    {
      "transform": [
        {
          "window": [
            {
              "op": "row_number",
              "as": "k"
            }
          ]
        },
        {
          "filter": "datum.k == 1"
        }
      ],
      "mark": {
        "type": "rule",
        "color": "#A19F9D",
        "strokeDash": [
          4,
          3
        ]
      },
      "encoding": {
        "y": {
          "field": "my",
          "type": "quantitative",
          "scale": {
            "zero": false
          },
          "title": "ICMS efetivo",
          "axis": {
            "format": ".0%",
            "tickCount": 4
          }
        }
      }
    },
    {
      "transform": [
        {
          "window": [
            {
              "op": "row_number",
              "as": "k"
            }
          ]
        },
        {
          "filter": "datum.k == 1"
        }
      ],
      "mark": {
        "type": "text",
        "align": "right",
        "baseline": "bottom",
        "fontSize": 9,
        "color": "#967100",
        "fontWeight": "bold"
      },
      "encoding": {
        "x": {
          "value": {
            "expr": "width"
          }
        },
        "y": {
          "value": -6
        },
        "text": {
          "value": "energia cara e ICMS alto"
        }
      }
    },
    {
      "transform": [
        {
          "window": [
            {
              "op": "row_number",
              "as": "k"
            }
          ]
        },
        {
          "filter": "datum.k == 1"
        }
      ],
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "bottom",
        "fontSize": 9,
        "color": "#605E5C"
      },
      "encoding": {
        "x": {
          "value": 4
        },
        "y": {
          "value": {
            "expr": "height - 4"
          }
        },
        "text": {
          "value": "energia barata e ICMS baixo"
        }
      }
    },
    {
      "mark": {
        "type": "circle",
        "opacity": 0.85
      },
      "encoding": {
        "x": {
          "field": "Tarifa sem tributos 12m",
          "type": "quantitative",
          "scale": {
            "zero": false
          },
          "title": "Tarifa sem tributos (R$/kWh)",
          "axis": {
            "format": "$,.2f",
            "tickCount": 4
          }
        },
        "y": {
          "field": "ICMS efetivo 12m",
          "type": "quantitative",
          "scale": {
            "zero": false
          },
          "title": "ICMS efetivo",
          "axis": {
            "format": ".0%",
            "tickCount": 4
          }
        },
        "color": {
          "condition": {
            "test": "(datum.__selected__ == ''on'' || datum[''Tarifa sem tributos 12m__highlightStatus''] == ''on'')",
            "value": "#F2C811"
          },
          "value": "#252423"
        },
        "size": {
          "condition": {
            "test": "(datum.__selected__ == ''on'' || datum[''Tarifa sem tributos 12m__highlightStatus''] == ''on'')",
            "value": 160
          },
          "value": 70
        },
        "opacity": {
          "condition": [
            {
              "test": "datum.__selected__ == ''off''",
              "value": 0.19
            },
            {
              "test": "datum[''Tarifa sem tributos 12m__highlightStatus''] == ''off''",
              "value": 0.19
            }
          ],
          "value": 0.85
        },
        "tooltip": [
          {
            "field": "Estado"
          },
          {
            "field": "rotulo",
            "title": "Valor (12 meses)"
          },
          {
            "field": "Custo elétrico 12m",
            "title": "Elétrico (R$/100 km)",
            "format": "$,.2f"
          },
          {
            "field": "Custo gasolina 12m",
            "title": "Gasolina (R$/100 km)",
            "format": "$,.2f"
          }
        ]
      }
    },
    {
      "transform": [
        {
          "filter": "!(datum.__selected__ == ''on'' || datum[''Tarifa sem tributos 12m__highlightStatus''] == ''on'')"
        }
      ],
      "mark": {
        "type": "text",
        "align": "left",
        "dx": 7,
        "fontSize": 9,
        "color": "#605E5C",
        "fontWeight": "normal"
      },
      "encoding": {
        "x": {
          "field": "Tarifa sem tributos 12m",
          "type": "quantitative",
          "scale": {
            "zero": false
          },
          "title": "Tarifa sem tributos (R$/kWh)",
          "axis": {
            "format": "$,.2f",
            "tickCount": 4
          }
        },
        "y": {
          "field": "ICMS efetivo 12m",
          "type": "quantitative",
          "scale": {
            "zero": false
          },
          "title": "ICMS efetivo",
          "axis": {
            "format": ".0%",
            "tickCount": 4
          }
        },
        "text": {
          "field": "UF"
        },
        "opacity": {
          "condition": [
            {
              "test": "datum.__selected__ == ''off''",
              "value": 0.22
            },
            {
              "test": "datum[''Tarifa sem tributos 12m__highlightStatus''] == ''off''",
              "value": 0.22
            }
          ],
          "value": 1.0
        }
      }
    },
    {
      "transform": [
        {
          "filter": "(datum.__selected__ == ''on'' || datum[''Tarifa sem tributos 12m__highlightStatus''] == ''on'')"
        }
      ],
      "mark": {
        "type": "text",
        "align": "left",
        "dx": 7,
        "fontSize": 11,
        "color": "#191919",
        "fontWeight": "bold"
      },
      "encoding": {
        "x": {
          "field": "Tarifa sem tributos 12m",
          "type": "quantitative",
          "scale": {
            "zero": false
          },
          "title": "Tarifa sem tributos (R$/kWh)",
          "axis": {
            "format": "$,.2f",
            "tickCount": 4
          }
        },
        "y": {
          "field": "ICMS efetivo 12m",
          "type": "quantitative",
          "scale": {
            "zero": false
          },
          "title": "ICMS efetivo",
          "axis": {
            "format": ".0%",
            "tickCount": 4
          }
        },
        "text": {
          "field": "UF"
        },
        "opacity": {
          "condition": [
            {
              "test": "datum.__selected__ == ''off''",
              "value": 0.22
            },
            {
              "test": "datum[''Tarifa sem tributos 12m__highlightStatus''] == ''off''",
              "value": 0.22
            }
          ],
          "value": 1.0
        }
      }
    }
  ]
}'
